    } else if (!isUndefined(value)) {
      fields[key] = true;
    }
  }

  return fields;
}

function collectDirtyFields<T>(
  data: T,
  formValues: T,
  dirtyFieldsFromValues?: Record<
    Extract<keyof T, string>,
    ReturnType<typeof markFieldsDirty> | boolean
  >,
) {
  if (!dirtyFieldsFromValues) {
    dirtyFieldsFromValues = markFieldsDirty(formValues);
  }

  for (const key in data) {
    const value = data[key];

    if (isTraversable(value)) {
      if (isUndefined(formValues) || isPrimitive(dirtyFieldsFromValues[key])) {
        dirtyFieldsFromValues[key] = markFieldsDirty(
          value,
          Array.isArray(value) ? [] : {},
        );
      } else {
        collectDirtyFields(
          value,
          isNullOrUndefined(formValues) ? {} : formValues[key],
          dirtyFieldsFromValues[key],
        );
      }
    } else {
      const formValue = formValues[key];
      dirtyFieldsFromValues[key] = !deepEqual(value, formValue);
    }
  }

  return dirtyFieldsFromValues;
}

/**
 * Recursively removes non-dirty entries from a collected dirty-fields tree.
 *
 * - Scalar fields marked as not dirty (`false`) are omitted.
 * - Objects that would only contain non-dirty entries are pruned entirely.
 * - Arrays keep their positions, but clean positions become `undefined`; when
 *   every position is clean, the whole array collapses to `undefined`.
 *
 * Returns the pruned value, or `undefined` when nothing dirty remains.
 */
function pruneDirtyFields(node: any): any {
  if (node === true) {
    return true;
  }

  if (Array.isArray(node)) {
    let hasDirty = false;
    const result = node.map((item) => {
      const pruned = pruneDirtyFields(item);
      if (!isUndefined(pruned)) {
        hasDirty = true;
      }
      return pruned;
    });

    return hasDirty ? result : undefined;
  }

